import{_ as a,o as e,c as r,ag as d}from"./chunks/framework.DMXcdKmJ.js";const _=JSON.parse('{"title":"使用应用开发工作区","description":"进入工程应用开发，完成首次模板初始化，使用 AI、编辑器和预览，并正确管理开发环境。","frontmatter":{"title":"使用应用开发工作区","description":"进入工程应用开发，完成首次模板初始化，使用 AI、编辑器和预览，并正确管理开发环境。","status":"reviewed","kind":"how-to"},"headers":[],"relativePath":"zh/guide/workspace.md","filePath":"zh/使用指南/使用应用开发工作区.md"}'),o={name:"zh/guide/workspace.md"};function i(h,t,n,l,p,s){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="使用应用开发工作区" tabindex="-1">使用应用开发工作区 <a class="header-anchor" href="#使用应用开发工作区" aria-label="Permalink to &quot;使用应用开发工作区&quot;">​</a></h1><p>“应用开发”是维护当前工程源码和查看开发预览的工作区。实际开发服务由平台提供，不需要在个人电脑另装一套平台服务。</p><p>开始前，使用有该工程权限的组织账号，在“工程管理”打开目标工程的 <strong>“应用开发”</strong>。</p><h2 id="_1-等待开发环境就绪" tabindex="-1">1. 等待开发环境就绪 <a class="header-anchor" href="#_1-等待开发环境就绪" aria-label="Permalink to &quot;1. 等待开发环境就绪&quot;">​</a></h2><p>页面会显示启动和读取状态。服务就绪前等待加载结束，不要同时反复启动、停止或删除工程。</p><p>如果开发环境已停止，点击 <strong>“启动开发环境”</strong>。显示“重新检查”“重试连接”等入口时，按当前提示操作；持续失败时，记录提示，请管理员确认服务配置、网络和容量。</p><p>页面提示开发访问名额被占用时，按提示退出不再使用的工程访问，必要时由管理员处理，不以删除工程释放名额。</p><h2 id="_2-新工程第一次选择模板" tabindex="-1">2. 新工程第一次选择模板 <a class="header-anchor" href="#_2-新工程第一次选择模板" aria-label="Permalink to &quot;2. 新工程第一次选择模板&quot;">​</a></h2><p>未初始化源码的工程会显示 <strong>“选择工程技术栈”</strong>，提供 Vue、React 与 JavaScript、TypeScript 的模板组合。</p><ol><li>按团队安排选择模板；没有既定安排时，先确认页面当前选项是否合适。</li><li>点击此页面的 <strong>“创建工程”</strong>。</li><li>等到初始化结束，工作区显示源码和页面。</li></ol><p>这是给已有工程生成初始源码，与工程列表里的“新建工程”是两步操作。初始化后不会再靠重选模板切换技术栈，不要为了切换选项反复初始化已有工程。</p><h2 id="_3-认识工作区" tabindex="-1">3. 认识工作区 <a class="header-anchor" href="#_3-认识工作区" aria-label="Permalink to &quot;3. 认识工作区&quot;">​</a></h2><table tabindex="0"><thead><tr><th>区域或入口</th><th>可以做什么</th></tr></thead><tbody><tr><td>AI</td><td>围绕当前工程讨论并协助修改源码，结果仍要自己检查</td></tr><tr><td>页面</td><td>查看开发预览和预览工具</td></tr><tr><td>数据点</td><td>查看或处理有权限的数据点相关内容</td></tr><tr><td>资源</td><td>管理工程上传的文件</td></tr><tr><td>编辑器</td><td>直接查看和维护源码</td></tr></tbody></table><p>可调整 AI 和工作台区域的宽度，在不同入口之间切换。修改代码后先保存，再检查预览结果。</p><p>AI 服务不可用或需要模型配置时，按工程的提示处理；编辑器、AI 和预览分别显示状态，不以其中一项可用推定其余也已就绪。</p><p>使用 AI 的完整步骤见<a href="/induframe-docs/zh/guide/ai-development.html">使用 AI 助手开发工程</a>，模型与凭据设置见<a href="/induframe-docs/zh/guide/ai-models.html">配置工程 AI 模型</a>。</p><h2 id="_4-正确停止与重新启动" tabindex="-1">4. 正确停止与重新启动 <a class="header-anchor" href="#_4-正确停止与重新启动" aria-label="Permalink to &quot;4. 正确停止与重新启动&quot;">​</a></h2><p>停止整个开发环境前，先保存内容并通知共同使用该工程的人员。确认 **“停止开发环境”**后，AI、编辑器和实时预览都会暂停，已保存的工程文件保留。</p><p>需要继续时，从工作区点击 <strong>“启动开发环境”</strong>，等待服务恢复。手动停止后，不要把页面重试当作已经明确启动。</p><p>关闭一个工具面板、停止预览服务、停止整个开发环境的影响不同。只想重新加载画面时，按<a href="/induframe-docs/zh/guide/preview.html">预览工程页面</a>使用“刷新”。</p><h2 id="_5-什么时候使用重建" tabindex="-1">5. 什么时候使用重建 <a class="header-anchor" href="#_5-什么时候使用重建" aria-label="Permalink to &quot;5. 什么时候使用重建&quot;">​</a></h2><p>重建会停止并重新创建开发服务，保留工程设计、页面源码和已发布版本。仍须先保存未保存内容，并核对当前工程。</p><p>只有确认开发服务需要恢复时，才按页面的重建入口操作。它不是删除工程，也不替代正式运行版本的更新；错误仍存在时保留提示交给维护人员。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>查看<a href="/induframe-docs/zh/guide/preview.html">预览工程页面</a>或<a href="/induframe-docs/zh/guide/project-files.html">查看和上传工程文件</a>。开始正式使用前，先理解<a href="/induframe-docs/zh/concepts/development-and-runtime.html">开发、发布与运行</a>的区别。</p>',25)])])}const u=a(o,[["render",i]]);export{_ as __pageData,u as default};
